import { env, waitUntil as workerWaitUntil } from "cloudflare:workers";

/** The Worker's bindings and secrets (wrangler.jsonc, .dev.vars locally). `Env` is generated by `wrangler types`. */
export function appEnv(): Env {
  return env;
}

/** Keeps the Worker alive until `promise` settles, after the response is sent. */
export function waitUntil(promise: Promise<unknown>): void {
  workerWaitUntil(promise);
}
